            using (SqlConnection conn = new SqlConnection(cs))
            {
                conn.Open();
                using (SqlCommand cmd = new SqlCommand(@"
                    SELECT TOP 1 L.Ltype, M.Mfiletype
                    FROM Listmenu L
                    LEFT JOIN Mission M ON M.Mid = L.Lxid
