                                mfiletype == "mm" ||
                                mfiletype == "mindmap" ||
                                mfiletype == "kitymind";

                            if (isMindMap)
                            {
                                Response.Redirect("program.aspx?lid=" + Server.UrlEncode(lid) + "&mid=" + Server.UrlEncode(mid) + "&mcid=" + Server.UrlEncode(mcid), true);
                            }
                        }
